// ==UserScript==
// @name            HWH Addon: Asgard Shop AutoBuy (settings)
// @namespace       hero-wars.asgard.shop.autobuy
// @version         0.1.11s
// @description     Native HWH panel (button in "Others"): buff priority (Coin), gold thresholds (Gold) in millions, drag&drop reordering, in-game icons, buff block (🚫) that greys the row and excludes it from buying, config in GM storage, Buy button. Shows already-bought counts (bought/limit per row + totals spent per rotation). 0.1.8s: anchors on readable names only (cost via CostData.get_outputDisplay, buy via the game's own shop method found at runtime) + drift check. 0.1.9s/0.1.10s: two-step actions (Buy / Import) with an explicit high-contrast confirm bar and a moving ⭐ marking the button to press now, plus an "applied" banner. 0.1.11s: on Import the ⭐ sits on "Load" while the box is empty and moves to "Import (preview)" once there is text.
// @match           https://www.hero-wars.com/*
// @grant           unsafeWindow
// @grant           GM_getValue
// @grant           GM_setValue
// @grant           GM_xmlhttpRequest
// @grant           GM_setClipboard
// @connect         raw.githubusercontent.com
// @connect         github.com
// @run-at          document-start
// ==/UserScript==

(function () {
  'use strict';

  var W = (typeof unsafeWindow !== 'undefined' && unsafeWindow) ? unsafeWindow : window;
  if (W.ASB && W.ASB.__loaded) { return; }

  var VERSION = '0.1.11s';
  var CFG_KEY = 'ASB_CONFIG';

  // ------------------------------------------------------------------ CATALOG
  // Catalogo buff Asgard per boss (entrambe le settimane): id -> {name, currency, cost, limit}.
  // Fonte: lib.data.clanRaid.buffShop (struttura) + nomi (live/doc). name=null per id senza nome.
  var ASB_CATALOG = {"bosses":{"1":{"locId":1,"unit":2015,"name":"Osh the Eternal Keeper (Cradle of the Stars)","buffs":{"61":{"name":"Defense Sphere Destroyer","currency":"gold","cost":1000000,"limit":5},"62":{"name":"Wormhole Suppressor","currency":"gold","cost":1000000,"limit":5},"63":{"name":"Meteors of Haste","currency":"gold","cost":1000000,"limit":5},"64":{"name":"Jumpstart","currency":"gold","cost":1000000,"limit":5},"65":{"name":"Defense Sphere Override","currency":"gold","cost":1000000,"limit":5},"66":{"name":"Astral Shield","currency":"coin","cost":50,"limit":1},"67":{"name":"Resilient Grove Keepers","currency":"coin","cost":50,"limit":1},"68":{"name":"Wakeful Undead","currency":"coin","cost":50,"limit":1},"69":{"name":"Ingenious Engineers","currency":"coin","cost":50,"limit":1},"70":{"name":"Healing Converter","currency":"coin","cost":50,"limit":1},"71":{"name":"Survivor's Willpower","currency":"coin","cost":50,"limit":1},"72":{"name":"Chosen by the Stars","currency":"coin","cost":50,"limit":1},"73":{"name":"Stellar Tank Resilience","currency":"coin","cost":50,"limit":1},"74":{"name":"Dreamer's Retaliation","currency":"coin","cost":50,"limit":1},"75":{"name":"Mages' Vigilance","currency":"coin","cost":50,"limit":1},"76":{"name":"Nightmare's Energy","currency":"coin","cost":50,"limit":1},"77":{"name":"Marksman Opportunity","currency":"coin","cost":50,"limit":1},"78":{"name":"Keeper's Blessing","currency":"coin","cost":50,"limit":1},"79":{"name":"Sphere Energy Unleashed","currency":"coin","cost":50,"limit":1},"80":{"name":"Immortal Hero","currency":"coin","cost":50,"limit":1},"81":{"name":"Insomnia","currency":"coin","cost":50,"limit":1}}},"2":{"locId":2,"unit":2025,"name":"Maestro (The Phantom Orchestra)","buffs":{"113":{"name":"Power Unleashed","currency":"gold","cost":1000000,"limit":5},"123":{"name":"Keepers of Balance","currency":"gold","cost":1000000,"limit":5},"126":{"name":"Total Elimination","currency":"gold","cost":1000000,"limit":5},"129":{"name":"Mischievous Team","currency":"gold","cost":1000000,"limit":5},"130":{"name":"Sparkling Mood","currency":"gold","cost":1000000,"limit":5},"112":{"name":"Vector of Might","currency":"coin","cost":150,"limit":1},"114":{"name":"Effective Tactics","currency":"coin","cost":50,"limit":1},"115":{"name":"The Tireless","currency":"coin","cost":50,"limit":1},"116":{"name":"Pillar of Confidence","currency":"coin","cost":50,"limit":1},"117":{"name":"Charmer's Skill","currency":"coin","cost":50,"limit":1},"118":{"name":"Unbridled Energy","currency":"coin","cost":50,"limit":1},"119":{"name":"Perfect Storm","currency":"coin","cost":50,"limit":1},"120":{"name":"Reverie Given Form","currency":"coin","cost":50,"limit":1},"122":{"name":"At the Limit","currency":"coin","cost":50,"limit":1},"125":{"name":"At the Speed of Light","currency":"coin","cost":50,"limit":1},"127":{"name":"Strength in Perseverance","currency":"coin","cost":50,"limit":1},"128":{"name":"Secret Weapon","currency":"coin","cost":50,"limit":1},"121":{"name":"The Healer's Gift","currency":"coin","cost":50,"limit":1},"133":{"name":"Through a Prism","currency":"coin","cost":50,"limit":1},"131":{"name":"The Chosen Protector","currency":"coin","cost":150,"limit":1},"132":{"name":"Power over Life","currency":"coin","cost":50,"limit":1}}}}};


  // ------------------------------------------------------------------ ICONS
  // Icone dei buff Asgard (clan raid). Fonte: atlas di gioco
  //   assets/js/adventure/adventure_buff_icons_small0.png  (frame "_<id>_buff_54").
  // Estratte offline dall'atlas e incapsulate come data-URL WebP (48px) per
  // renderle accanto ai buff senza dipendere dallo stato del gioco né dall'hash
  // di build del CDN. Chiave = buffId (AdventureMapBuff.get_id()).
  var ASB_ICONS = {"102":"data:image/webp;base64,","103":"data:image/webp;base64,","104":"data:image/webp;base64,","105":"data:image/webp;base64,","106":"data:image/webp;base64,","107":"data:image/webp;base64,","112":"data:image/webp;base64,","113":"data:image/webp;base64,","114":"data:image/webp;base64,","115":"data:image/webp;base64,","116":"data:image/webp;base64,","117":"data:image/webp;base64,","118":"data:image/webp;base64,","119":"data:image/webp;base64,","120":"data:image/webp;base64,","121":"data:image/webp;base64,","122":"data:image/webp;base64,","123":"data:image/webp;base64,","124":"data:image/webp;base64,","125":"data:image/webp;base64,","126":"data:image/webp;base64,","127":"data:image/webp;base64,","128":"data:image/webp;base64,","129":"data:image/webp;base64,","130":"data:image/webp;base64,","131":"data:image/webp;base64,","132":"data:image/webp;base64,","133":"data:image/webp;base64,","139":"data:image/webp;base64,","141":"data:image/webp;base64,","144":"data:image/webp;base64,","146":"data:image/webp;base64,","151":"data:image/webp;base64,","152":"data:image/webp;base64,","153":"data:image/webp;base64,","154":"data:image/webp;base64,","155":"data:image/webp;base64,","156":"data:image/webp;base64,","61":"data:image/webp;base64,","62":"data:image/webp;base64,","63":"data:image/webp;base64,","64":"data:image/webp;base64,","65":"data:image/webp;base64,","66":"data:image/webp;base64,","67":"data:image/webp;base64,","68":"data:image/webp;base64,","69":"data:image/webp;base64,","70":"data:image/webp;base64,","71":"data:image/webp;base64,","72":"data:image/webp;base64,","73":"data:image/webp;base64,","74":"data:image/webp;base64,","75":"data:image/webp;base64,","76":"data:image/webp;base64,","77":"data:image/webp;base64,","78":"data:image/webp;base64,","79":"data:image/webp;base64,","80":"data:image/webp;base64,","81":"data:image/webp;base64,"};

  // attende HWH (Classes/Data/Funcs)
  var loader = setInterval(function () {
    if (W.HWHClasses && W.HWHData && W.HWHFuncs) {
      clearInterval(loader);
      setTimeout(init, 800);
    }
  }, 500);

  // ---------------------------------------------------------------- anchors
  function G() { return W.selfGame; }
  function cls(n) { return G()[n]; }
  function getF(C, name) {
    var p = C && C.prototype && C.prototype.__properties__; if (!p) return null;
    if (typeof p[name] === 'string') return p[name];      // mappa keyed by nome leggibile (es. IntPropertyWriteable)
    for (var k in p) { if (p[k] === name) return k; }      // mappa keyed by nome minificato
    return null;
  }
  function getStatic(C, name) {
    var p = C && C.__properties__; if (!p) return null;
    for (var k in p) { if (p[k] === name) return k; } return null;
  }
  function getter(o, C, name) { var k = getF(C, name); try { return k ? o[k]() : undefined; } catch (e) { return undefined; } }
  function firstOf(o, C) { for (var k in o) { try { if (o[k] instanceof C) return o[k]; } catch (e) { } } return null; }
  function arrayOf(o, C) { for (var k in o) { var v = o[k]; if (Array.isArray(v) && v.length && v[0] instanceof C) return v; } return null; }

  function getPlayer() {
    var GM = cls('game.model.GameModel');
    var gm = GM[getStatic(GM, 'get_instance')]();
    return gm.player || firstOf(gm, cls('game.model.user.Player'));
  }

  // ---------------------------------------------------------------- READ
  // --- lettura robusta del costo (CostData / ResourceListData) --------------
  // Il gioco minifica e RINOMINA i campi fisici a ogni build. Qui si usa SOLO un
  // ancoraggio per nome leggibile (famiglia 2): get_outputDisplay() espone TUTTO il
  // costo come InventoryItem[] (oro id=2, monete id=30, item) con i getter
  // get_id()/get_amount(). Niente piu' campi minificati (Kd/Qp/Ap) nella via normale.
  var ASB_GOLD_ID = 2;    // risorsa "Gold"
  var ASB_COIN_ID = 30;   // monete Asgard ("Valor Emblem")
  function readCost(cost) {
    var out = { gold: null, coin: null };
    if (!cost) return out;
    try {
      var Cost = cls('game.data.cost.CostData');
      var Inv = cls('game.model.user.inventory.InventoryItem');
      var list = getter(cost, Cost, 'get_outputDisplay') || [];
      for (var i = 0; i < list.length; i++) {
        var id = getter(list[i], Inv, 'get_id');
        var amt = getter(list[i], Inv, 'get_amount');
        if (amt == null) continue;
        if (id === ASB_COIN_ID) out.coin = amt;
        else if (id === ASB_GOLD_ID) out.gold = amt;
        else if (out.coin == null) out.coin = amt;   // valuta-oggetto non riconosciuta
      }
    } catch (e) { }
    // fallback storici (solo se il getter non ha coperto nulla): campi nudi minificati
    try { if (out.gold == null && typeof cost.Ap === 'number' && cost.Ap > 0) out.gold = cost.Ap; } catch (e) { }
    if (out.coin == null) { try { if (cost.Kd) out.coin = Object.values(cost.Kd)[0].Qp; } catch (e) { } }
    return out;
  }

  // buyLimit per buffId: statico (lib.data.clanRaid.buffShop), incorporato in ASB_CATALOG.
  function limitForBuff(buffId) {
    if (buffId == null) return null;
    var bosses = ASB_CATALOG && ASB_CATALOG.bosses;
    if (bosses) { for (var id in bosses) { var b = bosses[id].buffs; if (b && b[buffId] && b[buffId].limit != null) return b[buffId].limit; } }
    return null;
  }

  function readShop() {
    var C = {
      Raid: cls('game.mechanics.clan_raid.PlayerClanRaidData'),
      Shop: cls('game.mechanics.clan_raid.shop.data.ClanRaidShopData'),
      Slot: cls('game.mechanics.clan_raid.shop.data.ClanRaidShopSlot'),
      Buff: cls('game.mechanics.adventure.model.map.AdventureMapBuff'),
      Desc: cls('game.mechanics.adventure.storage.AdventureMapBuffDescription'),
      Cost: cls('game.data.cost.CostData'),
      Prop: cls('engine.core.utils.property.IntPropertyWriteable'),
    };
    try {
      var raid = firstOf(getPlayer(), C.Raid);
      var shop = raid && firstOf(raid, C.Shop);
      if (!shop) return { ok: false, error: 'shop not found (open the Clan Raid)' };
      var slots = arrayOf(shop, C.Slot) || [];
      var items = slots.map(function (s, idx) {
        var buff = firstOf(s, C.Buff), cost = firstOf(s, C.Cost);
        var desc = buff ? firstOf(buff, C.Desc) : null;
        var cp = readCost(cost);
        var gold = cp.gold, coin = cp.coin;
        // boughtCount: unico campo IntPropertyWriteable dello slot (ancoraggio per classe).
        var prop = C.Prop ? firstOf(s, C.Prop) : null;
        var bought = prop ? getter(prop, C.Prop, 'get_value') : null;
        var buffId = buff ? getter(buff, C.Buff, 'get_id') : null;
        var limit = limitForBuff(buffId); if (limit == null && s.zfh != null) limit = s.zfh;
        return {
          slotId: (s.vja != null ? s.vja : (idx + 1)),   // chiave interna (l'ACT usa _raw)
          rank: (s.qB != null ? s.qB : (coin != null ? Math.round(coin / 50) : null)),
          limit: limit,
          bought: bought,
          remaining: (limit != null && bought != null) ? (limit - bought) : null,
          buffId: buffId,
          name: buff ? getter(buff, C.Buff, 'get_name') : ('slot' + (idx + 1)),
          value: buff ? getter(buff, C.Buff, 'get_value') : null,
          tex: desc ? desc.nlc : null,   // assetTexture_small, es. "_113_buff_54"
          gold: gold, coin: coin,
          _raw: s,                       // riferimento allo slot di modello (per l'ACT)
        };
      });
      return { ok: true, items: items };
    } catch (e) { return { ok: false, error: '' + e }; }
  }

  function readBalances() {
    return (async function () {
      var gold = null, coins = null, canGold = null, canCoins = null;
      try { gold = getter(getPlayer(), cls('game.model.user.Player'), 'get_gold'); } catch (e) { }
      try {
        var inv = await W.Send({ calls: [{ name: 'inventoryGet', args: {}, ident: 'body' }] });
        var resp = inv && inv.results && inv.results[0] && inv.results[0].result && inv.results[0].result.response;
        coins = ((resp && resp.coin) || {})['30'] || 0;
      } catch (e) { }
      try {
        var SD = cls('game.mechanics.clan_raid.shop.data.ClanRaidShopData');
        var shopData = firstOf(firstOf(getPlayer(), cls('game.mechanics.clan_raid.PlayerClanRaidData')), SD);
        if (shopData) { canGold = getter(shopData, SD, 'get_canBuyBuffWithGold'); canCoins = getter(shopData, SD, 'get_canBuyBuffWithCoins'); }
      } catch (e) { }
      return { ok: true, gold: gold, coins: coins, canGold: canGold, canCoins: canCoins };
    })();
  }

  // ---------------------------------------------------------------- CONFIG (per-boss store v2)
  // Store: { v:2, ioUrl, bosses: { "<bossId>": {gold:{reserve,rules}, coins:{order}, blocked:[]} } }.
  // bossId = locId (1 = Osh 2015, 2 = Maestro 2025). La config e' PER-BOSS: puoi
  // preparare i perk di un boss non attivo e li ritrovi quando gira.
  var STORE_V = 2;
  var DEFAULT_BOSS_CONFIG = { gold: { reserve: 5000000, rules: [] }, coins: { order: [] }, blocked: [] };
  var DEFAULT_CONFIG = DEFAULT_BOSS_CONFIG;   // compat
  var BOSS_SHORT = { '1': 'Osh', '2': 'Maestro' };

  function gmGet(key) { try { return (typeof GM_getValue === 'function') ? GM_getValue(key, undefined) : undefined; } catch (e) { return undefined; } }
  function gmSet(key, val) { try { if (typeof GM_setValue === 'function') { GM_setValue(key, val); return true; } } catch (e) { } return false; }

  function clone(o) { return JSON.parse(JSON.stringify(o)); }
  function newStore() { return { v: STORE_V, ioUrl: '', bosses: {} }; }
  function bossCfg(store, id) {
    if (!store.bosses) store.bosses = {};
    if (!store.bosses[id]) store.bosses[id] = clone(DEFAULT_BOSS_CONFIG);
    var b = store.bosses[id];
    if (!b.gold) b.gold = { reserve: 5000000, rules: [] };
    if (!b.coins) b.coins = { order: [] };
    if (!b.blocked) b.blocked = [];
    return b;
  }
  function readStoreRaw() {
    var v = gmGet(CFG_KEY);
    if (v == null) { try { var raw = W.localStorage.getItem(CFG_KEY); if (raw) return JSON.parse(raw); } catch (e) { } return null; }
    try { return (typeof v === 'string') ? JSON.parse(v) : v; } catch (e) { return null; }
  }
  // Normalizza/migra a store v2. liveId = boss attivo (per migrare la vecchia config flat).
  function ensureStore(parsed, liveId) {
    if (parsed && parsed.v === STORE_V && parsed.bosses) { parsed.ioUrl = parsed.ioUrl || ''; return parsed; }
    var store = newStore();
    if (parsed && (parsed.gold || parsed.coins || parsed.blocked)) {
      store.ioUrl = parsed.ioUrl || '';
      store.bosses[liveId || '1'] = {
        gold: parsed.gold || clone(DEFAULT_BOSS_CONFIG.gold),
        coins: parsed.coins || clone(DEFAULT_BOSS_CONFIG.coins),
        blocked: parsed.blocked || []
      };
    }
    return store;
  }
  function saveStore(store) {
    if (gmSet(CFG_KEY, store)) return true;
    try { W.localStorage.setItem(CFG_KEY, JSON.stringify(store)); return true; } catch (e) { return false; }
  }
  // compat API: lavorano sul boss selezionato
  function loadConfig() { return UI.store ? bossCfg(UI.store, UI.bossId) : clone(DEFAULT_BOSS_CONFIG); }
  function saveConfig() { return UI.store ? saveStore(UI.store) : false; }

  function mergeOrder(savedOrder, currentNames) {
    var out = (savedOrder || []).filter(function (n) { return currentNames.indexOf(n) >= 0; });
    currentNames.forEach(function (n) { if (out.indexOf(n) < 0) out.push(n); });
    return out;
  }

  // ---------------------------------------------------------------- IMPORT / EXPORT
  // Formato: JSON con "busta" { format, version, exportedAt, config }.
  // Import tollerante: accetta sia la busta sia un config nudo (retro-compatibile).
  var IO_FORMAT = 'asb-config';
  var IO_VERSION = 1;
  var IO_WEB_DEFAULT = 'https://github.com/HeroWarsTools/profiles/raw/refs/heads/main/Asgard_perks.json';

  function buildEnvelope() {
    commit();
    var st = UI.store || newStore();
    var bosses = {};
    Object.keys(st.bosses || {}).forEach(function (id) {
      var b = bossCfg(st, id);
      bosses[id] = {
        gold: { reserve: b.gold.reserve, rules: (b.gold.rules || []).slice() },
        coins: { order: (b.coins.order || []).slice() },
        blocked: (b.blocked || []).slice()
      };
    });
    return {
      format: IO_FORMAT, version: 2,
      exportedAt: new Date().toISOString(),
      activeBoss: UI.bossId,
      config: { v: STORE_V, ioUrl: st.ioUrl || '', bosses: bosses }
    };
  }

  function normalizeBossConfig(raw) {
    var warns = [];
    function num(v, d) { v = Number(v); return isFinite(v) ? v : d; }
    function strList(a) { return Array.isArray(a) ? a.filter(function (x) { return typeof x === 'string' && x; }) : []; }
    var gold = (raw.gold && typeof raw.gold === 'object') ? raw.gold : {};
    var rawRules = Array.isArray(gold.rules) ? gold.rules : [];
    var rules = rawRules.filter(function (r) { return r && typeof r.buff === 'string' && r.buff; }).map(function (r) {
      return { buff: r.buff, minBalance: Math.max(0, Math.round(num(r.minBalance, 10000000))), maxBuy: Math.max(0, Math.floor(num(r.maxBuy, 5))) };
    });
    if (rules.length !== rawRules.length) warns.push((rawRules.length - rules.length) + ' malformed gold rule(s) skipped');
    var coins = (raw.coins && typeof raw.coins === 'object') ? raw.coins : {};
    return {
      cfg: { gold: { reserve: Math.max(0, Math.round(num(gold.reserve, 5000000))), rules: rules }, coins: { order: strList(coins.order) }, blocked: strList(raw.blocked) },
      warns: warns
    };
  }

  // Accetta busta {format,config} o config nuda; store v2 ({bosses}) o v1 flat.
  function normalizeConfig(obj) {
    if (!obj || typeof obj !== 'object') throw new Error('JSON root is not an object');
    var raw = (obj.format === IO_FORMAT && obj.config && typeof obj.config === 'object') ? obj.config : obj;
    var warns = [];
    var store = newStore();
    store.ioUrl = (typeof raw.ioUrl === 'string') ? raw.ioUrl : ((UI.store && UI.store.ioUrl) || '');
    if (raw.bosses && typeof raw.bosses === 'object') {
      Object.keys(raw.bosses).forEach(function (id) {
        var r = normalizeBossConfig(raw.bosses[id] || {});
        store.bosses[id] = r.cfg;
        warns = warns.concat(r.warns.map(function (w) { return 'boss ' + id + ': ' + w; }));
      });
    } else if (raw.gold || raw.coins || raw.blocked) {
      var r1 = normalizeBossConfig(raw);
      var live = UI.liveBossId || '1';
      store.bosses[live] = r1.cfg;
      warns = warns.concat(r1.warns);
      warns.push('legacy flat config imported as boss ' + live);
    } else { warns.push('no recognized config found'); }
    return { store: store, warnings: warns };
  }

  function diffSummary(curStore, nextStore) {
    function counts(b) { b = b || DEFAULT_BOSS_CONFIG; return [(b.gold.rules || []).length, (b.coins.order || []).length, (b.blocked || []).length]; }
    var ids = {};
    Object.keys((curStore && curStore.bosses) || {}).forEach(function (k) { ids[k] = 1; });
    Object.keys((nextStore && nextStore.bosses) || {}).forEach(function (k) { ids[k] = 1; });
    var out = [];
    Object.keys(ids).sort().forEach(function (id) {
      var a = counts(curStore.bosses[id]), b = counts(nextStore.bosses[id]);
      out.push('boss ' + id + (id === UI.bossId ? ' *' : '') + ': gold rules ' + a[0] + '->' + b[0] + ', coin order ' + a[1] + '->' + b[1] + ', blocked ' + a[2] + '->' + b[2]);
    });
    out.push('(* = current selection)');
    return out.join('\n');
  }

  function applyConfig(store) {
    UI.store = store;
    UI.ioUrl = store.ioUrl || UI.ioUrl || '';
    UI.cfg = bossCfg(store, UI.bossId);
    UI.blocked = (UI.cfg.blocked || []).slice();
    saveStore(store);
    buildData();
  }

  function ioStatus(container, msg, ok) {
    var el = container.querySelector('#asb-io-status');
    if (!el) return;
    el.textContent = msg;
    el.className = ok ? 'asb-ok-box' : 'asb-hint';
  }

  // Stellina mobile (tab Import/Export): segna il bottone da premere ORA.
  // Casella vuota -> Load (scarica da web); con testo -> Import (anteprima); passo 2 -> Confirm.
  function ioStar(container) {
    var panel = container.querySelector('[data-panel="io"]');
    if (!panel) return;
    Array.prototype.forEach.call(panel.querySelectorAll('.asb-star'), function (s) { if (s.parentNode) s.parentNode.removeChild(s); });
    var step2 = panel.querySelector('#asb-io-step2');
    var ta = panel.querySelector('#asb-io-text');
    var id = (step2 && !step2.hidden) ? 'asb-io-confirm'
           : ((!ta || !String(ta.value).trim()) ? 'asb-io-load' : 'asb-io-import');
    var b = panel.querySelector('#' + id);
    if (!b) return;
    var sp = document.createElement('span');
    sp.className = 'asb-star';
    sp.textContent = '\u2B50 ';
    b.insertBefore(sp, b.firstChild);
  }

  function copyText(txt) {
    try { if (typeof GM_setClipboard === 'function') { GM_setClipboard(txt); return Promise.resolve(true); } } catch (e) { }
    if (navigator.clipboard && navigator.clipboard.writeText) return navigator.clipboard.writeText(txt).then(function () { return true; });
    return Promise.reject(new Error('clipboard unavailable'));
  }

  function downloadText(name, txt) {
    var blob = new Blob([txt], { type: 'application/json' });
    var url = URL.createObjectURL(blob);
    var a = document.createElement('a');
    a.href = url; a.download = name;
    document.body.appendChild(a); a.click();
    setTimeout(function () { try { a.remove(); } catch (e) { } URL.revokeObjectURL(url); }, 1000);
  }

  // GET di testo: GM_xmlhttpRequest (aggira il CORS) con fallback fetch.
  function fetchText(url) {
    return new Promise(function (resolve, reject) {
      try {
        if (typeof GM_xmlhttpRequest === 'function') {
          GM_xmlhttpRequest({
            method: 'GET', url: url,
            onload: function (r) { if (r.status >= 200 && r.status < 300) resolve(r.responseText); else reject(new Error('HTTP ' + r.status)); },
            onerror: function () { reject(new Error('network error')); },
            ontimeout: function () { reject(new Error('timeout')); }
          });
          return;
        }
      } catch (e) { }
      fetch(url).then(function (r) { if (!r.ok) throw new Error('HTTP ' + r.status); return r.text(); }).then(resolve, reject);
    });
  }

  // ---------------------------------------------------------------- CSS
  // NB: riscriviamo SEMPRE il contenuto (non solo se assente): cosi' dopo un
  // aggiornamento/re-iniezione la CSS non resta quella vecchia (bug: font a 12px).
  function ensureCss(doc) {
    var st = doc.getElementById('asb-css');
    if (!st) { st = doc.createElement('style'); st.id = 'asb-css'; doc.head.appendChild(st); }
    st.textContent =
      '#asb-wrap{font:16px/1.5 monospace;color:#eee;min-width:560px;max-width:720px}' +
      '.asb-tabbar{display:flex;gap:6px;margin:2px 0 10px}' +
      '.asb-tab{padding:4px 14px;border:1px solid #665;border-radius:8px;cursor:pointer;background:#2a2440;color:#dcd}' +
      '.asb-tab.active{background:#5a4a8a;border-color:#caa;color:#fff}' +
      '.asb-panel{display:none}.asb-panel.active{display:block}' +
      'table.asb{border-collapse:collapse;width:100%}' +
      'table.asb td,table.asb th{border:1px solid #554;padding:3px 6px;text-align:left}' +
      'table.asb th{background:#332b52}' +
      'table.asb input{width:72px;background:#120f22;color:#ffd;border:1px solid #665;border-radius:4px;padding:2px 4px}' +
      '.asb-ord{background:#3a3560;color:#fff;border:1px solid #6a5;border-radius:4px;padding:1px 8px;cursor:pointer;margin:0 2px;font-size:17px}' +
      '.asb-ord:hover:not(:disabled){background:#5a4f8a}' +
      '.asb-ord:disabled{opacity:.3;cursor:default}' +
      '.asb-hint{opacity:.65;margin:4px 0 8px}' +
      '.asb-m{opacity:.75;font-size:15px;color:#9cf}' +
      '.asb-ok{color:#7f7}' +
      '.asb-ico{width:33px;height:33px;vertical-align:-8px;margin-right:6px;border-radius:5px}' +
      '.asb-ico-none{display:inline-block;width:33px;height:33px;margin-right:6px;background:#221c33;border:1px solid #443;border-radius:5px;vertical-align:-8px}' +
      '.asb-grip{cursor:grab;color:#9c8;text-align:center;user-select:none;-webkit-user-select:none;touch-action:none;font-size:18px;white-space:nowrap}' +
      '.asb-grip:active{cursor:grabbing}' +
      '.asb-mfield{white-space:nowrap}.asb-mfield .asb-m{margin-left:3px;font-weight:bold}' +
      'tr.asb-dragging{opacity:.35}' +
      'tr.asb-drop-before td{border-top:2px solid #7f7 !important}' +
      'tr.asb-drop-after td{border-bottom:2px solid #7f7 !important}' +
      '#asb-dnd-ghost{position:fixed;z-index:2147483000;pointer-events:none;background:#2a2440;color:#fff;' +
        'border:1px solid #a9f;border-radius:6px;padding:3px 10px;font:16px monospace;opacity:.95;white-space:nowrap;' +
        'box-shadow:0 2px 8px rgba(0,0,0,.5)}' +
      'body.asb-dragging{user-select:none;-webkit-user-select:none}' +
      '.asb-buybtn{background:#2f6b2f;color:#fff;border:1px solid #5c5;border-radius:8px;padding:6px 18px;cursor:pointer;font-size:16px;margin:8px 6px 0 0}' +
      '.asb-buybtn:hover{background:#3d8a3d}' +
      '.asb-buybtn:disabled{opacity:.4;cursor:default}' +
      '.asb-buybtn.confirm{background:#8a4a2a;border-color:#c85}' +
      '.asb-buybtn.confirm:hover{background:#a85a34}' +
      '.asb-buybtn.ghost{background:#3a3560;border-color:#6a5}' +
      '.asb-buybtn.go{background:#2f8f3f;border-color:#7f7;font-size:18px;font-weight:bold;padding:8px 22px}' +
      '.asb-buybtn.go:hover{background:#39a84c}' +
      '.asb-buybtn.danger{background:#a5232a;border-color:#f77;font-size:19px;font-weight:bold;padding:9px 24px;animation:asb-pulse 1.5s infinite}' +
      '.asb-buybtn.danger:hover{background:#c22b33}' +
      '@keyframes asb-pulse{0%{box-shadow:0 0 0 0 rgba(255,90,90,.75)}70%{box-shadow:0 0 0 14px rgba(255,90,90,0)}100%{box-shadow:0 0 0 0 rgba(255,90,90,0)}}' +
      '.asb-confirmbar{margin-top:8px;padding:10px 12px;border:2px solid #f77;border-radius:10px;background:#2a1416}' +
      '.asb-steplabel{font-size:17px;font-weight:bold;color:#ffd;margin-bottom:8px;line-height:1.45}' +
      '.asb-step{display:inline-block;background:#4a3a7a;border:1px solid #a9f;border-radius:6px;padding:1px 8px;margin-right:4px}' +
      '.asb-arrow{color:#f9c;font-weight:bold;margin:0 6px}' +
      '.asb-star{display:inline-block;animation:asb-bounce .9s infinite}' +
      '@keyframes asb-bounce{0%,100%{transform:translateY(0)}50%{transform:translateY(-3px)}}' +
      '.asb-applied{margin-top:8px;padding:8px 12px;border:2px solid #7f7;border-radius:10px;background:#122a12;color:#cfc;font-size:17px;font-weight:bold}' +
      '.asb-diff{white-space:pre-wrap;font:15px monospace;background:#120f22;border:1px solid #443;border-radius:6px;padding:6px 8px;margin-bottom:8px;max-height:170px;overflow:auto}' +
      '.asb-ok-box{border-color:#7f7 !important;background:#122a12 !important;color:#cfc !important;font-weight:bold;opacity:1 !important}' +
      '.asb-log{max-height:150px;overflow:auto;background:#120f22;border:1px solid #554;border-radius:4px;padding:4px 6px;margin-top:8px;font-size:15px;white-space:pre-wrap}' +
      '.asb-name{font-size:20px;font-weight:600}' +
      '.asb-block{background:#2a2440;color:#fff;border:1px solid #665;border-radius:4px;cursor:pointer;font-size:15px;padding:0 6px;opacity:.4}' +
      '.asb-block:hover{opacity:1}' +
      '.asb-block.on{background:#8a2a2a;border-color:#e66;opacity:1}' +
      'tr.asb-blocked{filter:grayscale(1);opacity:.5}' +
      'tr.asb-blocked .asb-name{text-decoration:line-through}' +
      '.asb-blocknote{opacity:.6;font-size:14px}' +
      '#asb-io-status{white-space:pre-wrap;max-height:170px;overflow:auto;background:#120f22;border:1px solid #443;border-radius:4px;padding:4px 6px;margin-top:8px}' +
      '#asb-io-url{background:#120f22;color:#ffd;border:1px solid #665;border-radius:4px;padding:2px 4px}' +
      '.asb-bossbar{margin:0 0 8px;font-size:15px}' +
      '.asb-bossbtn{background:#2a2440;color:#dcd;border:1px solid #665;border-radius:8px;padding:3px 12px;margin-right:6px;cursor:pointer;font-size:15px}' +
      '.asb-bossbtn.active{background:#5a4a8a;border-color:#caa;color:#fff}' +
      '.asb-live{color:#7f7;font-size:13px}';
  }

  function iconTag(buffId) {
    var u = (buffId != null) ? ASB_ICONS[buffId] : null;
    if (u) return '<img class="asb-ico" src="' + u + '" alt="">';
    return '<span class="asb-ico-none" title="icon not available"></span>';
  }

  // ---------------------------------------------------------------- UI STATE
  var UI = { data: null, coinOrder: [], goldRows: [], cfg: null, activeTab: 'gold', bal: null, savedFlash: false, buffIdByName: {}, buyLog: [], blocked: [], ioUrl: '', store: null, bossId: null, liveBossId: null, liveShop: null };

  // nomi dei buff bloccati (🚫): riga desaturata e mai acquistati.
  function isBlocked(name) { return UI.blocked.indexOf(name) >= 0; }
  function escAttr(s) { return String(s).replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;'); }

  function fmt(n) {
    if (n == null || n === '' || isNaN(n)) return 'n/a';
    n = Number(n);
    var a = Math.abs(n);
    if (a >= 1e6) return (n / 1e6).toFixed(2).replace(/\.?0+$/, '') + 'M';
    if (a >= 1e3) return (n / 1e3).toFixed(1).replace(/\.0$/, '') + 'k';
    return String(n);
  }
  // valore in milioni per gli input oro (es. 10000000 -> "10")
  function millions(n) { if (n == null || n === '' || isNaN(n)) return ''; return String(Math.round((n / 1e6) * 1000) / 1000); }
  function sleep(ms) { return new Promise(function (r) { setTimeout(r, ms); }); }

  // shop sintetico per un boss non attivo, dal catalogo statico
  function synthShop(bossId) {
    var b = ASB_CATALOG.bosses[bossId];
    var items = [];
    if (b && b.buffs) {
      Object.keys(b.buffs).forEach(function (id) {
        var x = b.buffs[id];
        items.push({
          name: x.name || ('Buff #' + id), buffId: parseInt(id, 10),
          gold: x.currency === 'gold' ? x.cost : null,
          coin: x.currency === 'coin' ? x.cost : null,
          limit: x.limit, remaining: x.limit, bought: 0, rank: null, slotId: null, _raw: null, synthetic: true
        });
      });
    }
    return { ok: true, items: items, synthetic: true, bossId: bossId };
  }

  function detectLiveBoss(shop) {
    if (!shop || !shop.ok || !shop.items.length) return UI.liveBossId || '1';
    var mx = 0;
    shop.items.forEach(function (s) { if (s.buffId > mx) mx = s.buffId; });
    return mx >= 100 ? '2' : '1';
  }

  function buildData() {
    var live = readShop();
    UI.liveShop = live;
    UI.liveBossId = detectLiveBoss(live);
    if (!UI.store) UI.store = ensureStore(readStoreRaw(), UI.liveBossId);
    if (!UI.bossId) UI.bossId = UI.liveBossId;
    var shop = (UI.bossId === UI.liveBossId) ? live : synthShop(UI.bossId);
    var cfg = bossCfg(UI.store, UI.bossId);
    UI.cfg = cfg;
    UI.ioUrl = UI.store.ioUrl || UI.ioUrl || '';
    UI.shop = shop;
    UI.savedFlash = false;
    var goldItems = shop.ok ? shop.items.filter(function (s) { return s.gold != null; }) : [];
    var epicItems = shop.ok ? shop.items.filter(function (s) { return s.coin != null; }) : [];

    UI.buffIdByName = {};
    UI.itemByName = {};
    if (shop.ok) shop.items.forEach(function (s) { if (s.buffId != null) UI.buffIdByName[s.name] = s.buffId; UI.itemByName[s.name] = s; });

    var epicNames = epicItems.map(function (s) { return s.name; });
    UI.coinOrder = mergeOrder(cfg.coins.order, epicNames);
    UI.blocked = (cfg.blocked || []).slice();
    UI.epicCost = {}; epicItems.forEach(function (s) { UI.epicCost[s.name] = s.coin; });

    var rulesByName = {}; (cfg.gold.rules || []).forEach(function (r) { rulesByName[r.buff] = r; });
    var goldNames = goldItems.length ? goldItems.map(function (s) { return s.name; })
      : (cfg.gold.rules || []).map(function (r) { return r.buff; });
    UI.goldRows = goldNames.map(function (n) {
      var r = rulesByName[n] || { minBalance: 10000000, maxBuy: 5 };
      return { buff: n, minBalance: r.minBalance, maxBuy: r.maxBuy, cost: goldItems.filter(function (s) { return s.name === n; })[0] || null };
    });
  }

  function bossLabel(id) {
    var b = ASB_CATALOG.bosses[id];
    var short = BOSS_SHORT[id] || ('Boss ' + id);
    return short + (b && b.unit ? ' (' + b.unit + ')' : '');
  }
  function bossBarHTML() {
    var ids = Object.keys(ASB_CATALOG.bosses).sort();
    var h = '<div class="asb-bossbar">Perks for boss: ';
    ids.forEach(function (id) {
      h += '<button class="asb-bossbtn' + (id === UI.bossId ? ' active' : '') + '" data-boss="' + id + '" title="' + escAttr((ASB_CATALOG.bosses[id] || {}).name || id) + '">' +
           escAttr(bossLabel(id)) + (id === UI.liveBossId ? ' <span class="asb-live">&#9733; live</span>' : '') + '</button>';
    });
    if (UI.bossId !== UI.liveBossId) h += '<span class="asb-hint">(not the active boss &mdash; buying disabled; settings are stored and will apply when it rotates in)</span>';
    h += '</div>';
    return h;
  }

  // --- acquisti gia' fatti (colonna "Bought" + riga di riepilogo) -------------
  // bought = contatore del modello (IntPropertyWriteable dello slot): quanti pezzi
  // di quel buff sono gia' stati comprati in QUESTA rotazione dello shop.
  function boughtCell(it) {
    if (!it || it.bought == null) return '&mdash;';
    var lim = (it.limit != null) ? it.limit : '?';
    var done = (it.limit != null && it.bought >= it.limit);
    return it.bought + '/' + lim + (done ? ' <span class="asb-ok">&#10003;</span>' : '');
  }
  // totali spesi nella rotazione corrente (solo shop live, non sintetico)
  function spentSummary() {
    var s = { coin: 0, gold: 0, coinBought: 0, coinLimit: 0, goldBought: 0, goldLimit: 0, live: false };
    if (UI.shop && UI.shop.ok && !UI.shop.synthetic) {
      s.live = true;
      UI.shop.items.forEach(function (it) {
        var b = it.bought || 0;
        if (it.coin != null) { s.coinBought += b; s.coinLimit += (it.limit || 0); s.coin += b * it.coin; }
        else if (it.gold != null) { s.goldBought += b; s.goldLimit += (it.limit || 0); s.gold += b * it.gold; }
      });
    }
    return s;
  }

  function bodyHTML() {
    var b = UI.bal || {};
    var tab = UI.activeTab || 'gold';
    var h = '<div id="asb-wrap">';
    h += bossBarHTML();
    h += '<div class="asb-hint">Gold: ' + fmt(b.gold) +
      ' · Asgard coins: ' + (b.coins == null ? 'n/a' : b.coins) +
      ' · coins OK: ' + b.canCoins + ' · gold OK: ' + b.canGold + '</div>';
    var sp = spentSummary();
    h += '<div class="asb-hint">Already bought: ' + (sp.live
      ? 'coins <b>' + sp.coinBought + '/' + sp.coinLimit + '</b> (' + fmt(sp.coin) + ' coins spent) · ' +
        'gold <b>' + sp.goldBought + '/' + sp.goldLimit + '</b> (' + fmt(sp.gold) + ' gold spent)'
      : '&mdash; open the active boss to see real counts') + '</div>';
    h += '<div class="asb-tabbar"><div class="asb-tab' + (tab === 'gold' ? ' active' : '') + '" data-tab="gold">Gold</div>' +
      '<div class="asb-tab' + (tab === 'coins' ? ' active' : '') + '" data-tab="coins">Coin</div>' +
      '<div class="asb-tab' + (tab === 'buy' ? ' active' : '') + '" data-tab="buy">Buy</div>' +
      '<div class="asb-tab' + (tab === 'io' ? ' active' : '') + '" data-tab="io">Import/Export</div></div>';

    // TAB GOLD
    h += '<div class="asb-panel' + (tab === 'gold' ? ' active' : '') + '" data-panel="gold">';
    h += '<div class="asb-hint">Buy with gold only when the balance exceeds the buff threshold (plus reserve).</div>';
    h += '<div>Gold reserve: <span class="asb-mfield"><input id="asb-reserve" type="text" value="' + millions(UI.cfg.gold.reserve) + '"><span class="asb-m">M</span></span></div>';
    h += '<table class="asb"><tr><th>Buff</th><th>Cost</th><th title="Already bought / max">Bought</th><th>Gold threshold</th><th>Max</th><th title="Block/unblock buying">\uD83D\uDEAB</th></tr>';
    UI.goldRows.forEach(function (r, i) {
      var bid = r.cost ? r.cost.buffId : UI.buffIdByName[r.buff];
      var blk = isBlocked(r.buff);
      h += '<tr class="' + (blk ? 'asb-blocked' : '') + '"><td class="asb-name">' + iconTag(bid) + r.buff + '</td><td>' + fmt(r.cost ? r.cost.gold : null) + '</td>' +
        '<td>' + boughtCell(r.cost) + '</td>' +
        '<td><span class="asb-mfield"><input data-gold-thr="' + i + '" type="text" value="' + millions(r.minBalance) + '"><span class="asb-m">M</span></span></td>' +
        '<td><input data-gold-max="' + i + '" type="text" value="' + r.maxBuy + '"></td>' +
        '<td><button class="asb-block' + (blk ? ' on' : '') + '" data-block-name="' + escAttr(r.buff) + '"       title="' + (blk ? 'Allow buying again' : 'Block buying and grey out the row') + '">\uD83D\uDEAB</button></td></tr>';
    });
    h += '</table></div>';

    // TAB COIN
    h += '<div class="asb-panel' + (tab === 'coins' ? ' active' : '') + '" data-panel="coins">';
    h += '<div class="asb-hint">Priority: the first row is bought first. Asgard coins are spent fully. ' +
      '<span id="asb-saved" class="asb-ok">' + (UI.savedFlash ? 'order saved' : '') + '</span></div>';
    h += '<table class="asb"><tr><th title="Drag the row to reorder">#</th><th>Buff</th><th>Cost</th><th title="Already bought / max">Bought</th><th>Order</th><th title="Block/unblock buying">\uD83D\uDEAB</th></tr>';
    UI.coinOrder.forEach(function (n, i) {
      var c = UI.epicCost[n];
      var last = UI.coinOrder.length - 1;
      var nameAttr = String(n).replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;');
      var blk = isBlocked(n);
      h += '<tr data-row="' + i + '" data-name="' + nameAttr + '" class="' + (blk ? 'asb-blocked' : '') + '"><td class="asb-grip" title="Drag to reorder">\u270B ' + (i + 1) + '</td><td class="asb-name">' + iconTag(UI.buffIdByName[n]) + n + '</td><td>' + (c == null ? '-' : c) + '</td><td>' + boughtCell(UI.itemByName[n]) + '</td><td>' +
        '<button class="asb-ord" data-i="' + i + '" data-dir="up"' + (i === 0 ? ' disabled' : '') + ' title="Move up">&uarr;</button>' +
        '<button class="asb-ord" data-i="' + i + '" data-dir="down"' + (i === last ? ' disabled' : '') + ' title="Move down">&darr;</button>' +
        '</td><td><button class="asb-block' + (blk ? ' on' : '') + '" data-block-name="' + nameAttr + '"       title="' + (blk ? 'Allow buying again' : 'Block buying and grey out the row') + '">\uD83D\uDEAB</button></td></tr>';
    });
    h += '</table></div>';

    // TAB BUY
    h += '<div class="asb-panel' + (tab === 'buy' ? ' active' : '') + '" data-panel="buy">';
    h += buyPanelHTML();
    h += '</div>';

    // TAB IMPORT/EXPORT
    h += '<div class="asb-panel' + (tab === 'io' ? ' active' : '') + '" data-panel="io">';
    h += ioPanelHTML();
    h += '</div></div>';
    return h;
  }

  // ---------------------------------------------------------------- PLAN / BUY (ACT)
  function remainingOf(it) { return (it.remaining != null) ? it.remaining : (it.limit || 1); }

  function computePlan() {
    var items = (UI.shop && UI.shop.ok) ? UI.shop.items : [];
    var byName = {}; items.forEach(function (s) { byName[s.name] = s; });
    var bal = UI.bal || {};
    var coins = (bal.coins != null) ? bal.coins : 0;
    var gold = (bal.gold != null) ? bal.gold : 0;
    var reserve = UI.cfg.gold.reserve || 0;
    var plan = [];
    // Coin: per priorità, spende le monete fino a esaurirle
    UI.coinOrder.forEach(function (name) {
      var it = byName[name]; if (!it || it.coin == null || isBlocked(name)) return;
      var rem = remainingOf(it);
      while (rem > 0 && coins >= it.coin) { plan.push({ slotId: it.slotId, buff: name, buffId: it.buffId, currency: 'coin', unit: it.coin }); coins -= it.coin; rem--; }
    });
    // Gold: solo se dopo l'acquisto resti sopra soglia + riserva
    UI.goldRows.forEach(function (r) {
      var it = byName[r.buff]; if (!it || it.gold == null || isBlocked(r.buff)) return;
      var rem = remainingOf(it), cnt = 0;
      while (rem > 0 && cnt < r.maxBuy && (gold - it.gold) >= (r.minBalance + reserve)) {
        plan.push({ slotId: it.slotId, buff: r.buff, buffId: it.buffId, currency: 'gold', unit: it.gold });
        gold -= it.gold; rem--; cnt++;
      }
    });
    var groups = [];
    plan.forEach(function (p) {
      var key = p.buffId + '|' + p.currency;
      var g = null; for (var i = 0; i < groups.length; i++) { if (groups[i].key === key) { g = groups[i]; break; } }
      if (!g) { g = { key: key, buff: p.buff, buffId: p.buffId, currency: p.currency, unit: p.unit, count: 0, total: 0 }; groups.push(g); }
      g.count++; g.total += p.unit;
    });
    return { list: plan, groups: groups };
  }

  function buyPanelHTML() {
    var bal = UI.bal || {};
    var plan = computePlan();
    var notLive = UI.bossId !== UI.liveBossId;
    var h = '<div class="asb-hint">Buy plan: <b>Coin</b> by priority (spends coins), <b>Gold</b> only if you stay above <i>threshold + reserve</i>. Balances: Gold ' + fmt(bal.gold) + ' · Coins ' + (bal.coins == null ? 'n/a' : bal.coins) + '.</div>';
    if (notLive) h += '<div class="asb-hint">This is boss <b>' + escAttr(bossLabel(UI.bossId)) + '</b>, not the active one: <b>buying is disabled</b>. Plan shown is only a preview with current balances.</div>';
    if (!plan.groups.length) {
      h += '<div class="asb-hint">No purchases planned (not enough resources or shop empty).</div>';
    } else {
      h += '<table class="asb"><tr><th>Buff</th><th>Currency</th><th>Unit</th><th>Qty</th><th>Total</th></tr>';
      plan.groups.forEach(function (g) {
        h += '<tr><td class="asb-name">' + iconTag(g.buffId) + g.buff + '</td><td>' + g.currency + '</td><td>' + fmt(g.unit) + '</td><td>' + g.count + '</td><td>' + fmt(g.total) + '</td></tr>';
      });
      h += '</table>';
      h += '<div class="asb-hint">Total: <b>' + plan.list.length + '</b> purchases (Coin ' + plan.list.filter(function (p) { return p.currency === 'coin'; }).length + ' · Gold ' + plan.list.filter(function (p) { return p.currency === 'gold'; }).length + ').</div>';
    }
    if (UI.appliedMsg) h += '<div class="asb-applied">&#10003; ' + escAttr(UI.appliedMsg) + '</div>';
    // PASSO 1 — prepara il piano (stellina = bottone da premere ora)
    h += '<div id="asb-buy-step1" class="asb-steprow">';
    h += '<button class="asb-buybtn ghost" id="asb-buy-calc">Recalculate</button>';
    h += '<button class="asb-buybtn go" id="asb-buy-run"' + (plan.list.length && !notLive ? '' : ' disabled') + ' data-n="' + plan.list.length + '">' +
         (plan.list.length && !notLive ? ('<span class="asb-star">\u2B50</span> Buy ' + plan.list.length + ' buffs') : 'Buy') + '</button>';
    h += '</div>';
    // PASSO 2 — conferma esplicita (barra ad alto contrasto, stesso pannello; stellina sul Confirm)
    h += '<div id="asb-buy-step2" class="asb-confirmbar" hidden>' +
         '<div class="asb-steplabel">Ready to buy <b>' + plan.list.length + '</b> buffs &mdash; press the <b>starred</b> button to confirm.</div>' +
         '<button class="asb-buybtn ghost" id="asb-buy-cancel">Cancel</button>' +
         '<button class="asb-buybtn danger" id="asb-buy-confirm" data-n="' + plan.list.length + '"><span class="asb-star">\u2B50</span> Confirm ' + plan.list.length + ' purchases</button>' +
         '</div>';
    h += '<div id="asb-buy-log" class="asb-log">' + UI.buyLog.join('\n') + '</div>';
    return h;
  }

  function ioPanelHTML() {
    var url = UI.ioUrl || IO_WEB_DEFAULT;
    var h = '<div class="asb-hint">Export/import this configuration as JSON (backup or sharing). Import <b>replaces</b> the current config after a preview.</div>';
    h += '<div style="margin:6px 0"><button class="asb-buybtn ghost" id="asb-io-export">Export</button>' +
         '<button class="asb-buybtn ghost" id="asb-io-copy">Copy</button>' +
         '<button class="asb-buybtn ghost" id="asb-io-download">Download</button></div>';
    h += '<div style="margin:6px 0">Load from web: <input id="asb-io-url" type="text" value="' + escAttr(url) + '" style="width:58%"> ' +
         '<button class="asb-buybtn ghost" id="asb-io-load">Load</button></div>';
    h += '<textarea id="asb-io-text" spellcheck="false" style="width:100%;height:160px;background:#120f22;color:#ffd;border:1px solid #665;border-radius:4px;font:15px monospace;box-sizing:border-box"></textarea>';
    // PASSO 1 — anteprima (stellina gestita a runtime da ioStar: su Load se la casella è vuota)
    h += '<div id="asb-io-step1" class="asb-steprow"><button class="asb-buybtn go" id="asb-io-import">Import (preview)</button></div>';
    // PASSO 2 — conferma esplicita (stellina sul Confirm, gestita da ioStar)
    h += '<div id="asb-io-step2" class="asb-confirmbar" hidden>' +
         '<div class="asb-steplabel">Preview ready &mdash; press the <b>starred</b> button to replace your config (this <b>overwrites</b> the current one).</div>' +
         '<div id="asb-io-diff" class="asb-diff"></div>' +
         '<button class="asb-buybtn ghost" id="asb-io-cancel">Cancel</button>' +
         '<button class="asb-buybtn danger" id="asb-io-confirm">Confirm replace</button>' +
         '</div>';
    h += '<div id="asb-io-status" class="asb-hint"></div>';
    return h;
  }

  // ACT: invia il comando di acquisto tramite il CommandManager del gioco
  // (stesso percorso di ClanRaidShopData.zdb usato dal mediator dello shop).
  // Il comando FQN e' stabile; il metodo di invio del CommandManager e' individuato
  // a runtime (il nome e' minificato e cambia tra build).
  function findSendKey(CM) {
    var p = CM && CM.prototype; if (!p) return null;
    var old = [];
    for (var k in p) {
      if (typeof p[k] !== 'function') continue;
      var s = '' + p[k];
      // build 2026-10: il metodo di invio chiama cmd.Yz(this.player) e this.player.mih(...)
      if (s.indexOf('.Yz(this.player)') >= 0) return k;
      if (s.indexOf('this.player.mih(') >= 0) return k;
      // build precedenti
      if (s.indexOf('.e4a(') >= 0 || s.indexOf('this.player.aJ()') >= 0) old.push(k);
    }
    return old[0] || null;
  }

  // Nomi (minificati) del costruttore del comando: Haxe li espone su .name e/o
  // su prototype.__class__.name / __name__. Servono per riconoscere il metodo di
  // acquisto dello shop senza conoscerne il nome (che cambia a ogni build).
  function cmdCtorNames(Cmd) {
    var names = [];
    try { if (Cmd.name) names.push(Cmd.name); } catch (e) { }
    try { if (Cmd.prototype && Cmd.prototype.__class__ && Cmd.prototype.__class__.name) names.push(Cmd.prototype.__class__.name); } catch (e) { }
    try { if (Cmd.__name__) names.push(Cmd.__name__); } catch (e) { }
    return names;
  }

  // Trova il metodo di acquisto dello shop data: e' il metodo (nome minificato)
  // il cui sorgente contiene "new <CtorCmd>(" — cioe' costruisce il comando di
  // acquisto. E' la stessa via che usa il gioco (mediator dello shop).
  function findShopBuyMethod(shopData, Cmd) {
    if (!shopData || !Cmd) return null;
    var names = cmdCtorNames(Cmd);
    if (!names.length) return null;
    var seen = {};
    for (var o = Object.getPrototypeOf(shopData); o && o !== Object.prototype; o = Object.getPrototypeOf(o)) {
      for (var k in o) {
        if (seen[k]) continue; seen[k] = true;
        var f; try { f = o[k]; } catch (e) { continue; }
        if (typeof f !== 'function') continue;
        var s = '' + f;
        for (var i = 0; i < names.length; i++) { if (s.indexOf('new ' + names[i] + '(') >= 0) return k; }
      }
    }
    return null;
  }

  function buySlot(slotId) {
    return Promise.resolve().then(function () {
      var items = (UI.shop && UI.shop.ok) ? UI.shop.items : [];
      var raw = null; for (var i = 0; i < items.length; i++) { if (items[i].slotId === slotId) { raw = items[i]._raw; break; } }
      if (!raw) throw new Error('slot ' + slotId + ' not found');
      var Cmd = cls('game.command.rpc.clanboss.CommandClanBossShopBuy');
      var CM = cls('game.command.CommandManager');
      if (!Cmd) throw new Error('command class not found');
      // VIA 1 (preferita): il metodo di acquisto dello shop data, individuato a
      // runtime cercando "new <CtorCmd>(" sul prototipo. Fa esattamente cio' che fa
      // il gioco (costruisce il comando e lo invia), quindi non dipende dal nome
      // minificato ne' del metodo ne' del send del CommandManager.
      try {
        var SD = cls('game.mechanics.clan_raid.shop.data.ClanRaidShopData');
        var shopData = firstOf(firstOf(getPlayer(), cls('game.mechanics.clan_raid.PlayerClanRaidData')), SD);
        if (shopData) {
          var buyKey = findShopBuyMethod(shopData, Cmd);
          if (buyKey && typeof shopData[buyKey] === 'function') { shopData[buyKey](raw); return true; }
        }
      } catch (e) { }
      // VIA 2 (fallback): costruisci il comando e invialo col CommandManager.
      if (!CM) throw new Error('command classes not found');
      var GM = cls('game.model.GameModel'); var gm = GM[getStatic(GM, 'get_instance')]();
      var cm = firstOf(gm, CM); if (!cm) throw new Error('CommandManager not found');
      // il comando legge da solo lo slot (a.Aja): passiamo l'oggetto _raw, non il slotId.
      var sendKey = findSendKey(CM) || (typeof cm['Tb'] === 'function' ? 'Tb' : 'Sb');
      cm[sendKey](new Cmd(raw));
      return true;
    });
  }

  // ---------------------------------------------------------------- DRIFT CHECK
  // Verifica che gli ancoraggi "per nome leggibile" esistano ancora. Serve a
  // distinguere "il gioco ha rinominato qualcosa" da "config sbagliata": se un
  // build futuro rompe un ancoraggio, lo script lo DICE invece di fallire in silenzio.
  function driftCheck() {
    var issues = [], good = [];
    function need(fqn, label) {
      var C = null; try { C = cls(fqn); } catch (e) { }
      if (C) good.push(label); else issues.push('missing class: ' + label + ' (' + fqn + ')');
      return C;
    }
    function needGetter(C, name, label) {
      if (!C) return;
      if (getF(C, name)) good.push(label); else issues.push('missing getter: ' + label + ' (' + name + ')');
    }
    var Cost = need('game.data.cost.CostData', 'CostData');
    var Inv = need('game.model.user.inventory.InventoryItem', 'InventoryItem');
    var Prop = need('engine.core.utils.property.IntPropertyWriteable', 'IntPropertyWriteable');
    var Cmd = need('game.command.rpc.clanboss.CommandClanBossShopBuy', 'CommandClanBossShopBuy');
    var CM = need('game.command.CommandManager', 'CommandManager');
    var SD = need('game.mechanics.clan_raid.shop.data.ClanRaidShopData', 'ClanRaidShopData');
    needGetter(Cost, 'get_outputDisplay', 'CostData.get_outputDisplay');
    needGetter(Inv, 'get_id', 'InventoryItem.get_id');
    needGetter(Inv, 'get_amount', 'InventoryItem.get_amount');
    needGetter(Prop, 'get_value', 'IntPropertyWriteable.get_value');
    var sendKey = null, buyKey = null;
    try { if (CM) { sendKey = findSendKey(CM); if (sendKey) good.push('CommandManager.send=' + sendKey); else issues.push('CommandManager send method not found'); } } catch (e) { }
    try {
      var shopData = SD ? firstOf(firstOf(getPlayer(), cls('game.mechanics.clan_raid.PlayerClanRaidData')), SD) : null;
      if (!shopData) good.push('shop not open (buy-method check skipped)');
      else if (Cmd) { buyKey = findShopBuyMethod(shopData, Cmd); if (buyKey) good.push('shop.buy=' + buyKey); else issues.push('shop buy method not found (CommandManager fallback)'); }
    } catch (e) { issues.push('runtime probe: ' + e); }
    return { ok: issues.length === 0, issues: issues, good: good, sendKey: sendKey, buyKey: buyKey };
  }

  function buyLog(container, msg) {
    UI.buyLog.push(msg);
    if (UI.buyLog.length > 200) UI.buyLog = UI.buyLog.slice(-200);
    var el = container.querySelector('#asb-buy-log');
    if (el) { el.textContent = UI.buyLog.join('\n'); el.scrollTop = el.scrollHeight; }
  }

  function executePlan(container, btn) {
    if (UI.bossId !== UI.liveBossId) { buyLog(container, 'Buying disabled: not the active boss.'); return; }
    var plan = computePlan().list;
    if (!plan.length) return;
    btn.disabled = true; btn.textContent = 'Buying...';
    (async function () {
      buyLog(container, 'Starting: ' + plan.length + ' purchases...');
      var ok = 0, err = 0;
      for (var i = 0; i < plan.length; i++) {
        var p = plan[i];
        try {
          await buySlot(p.slotId); ok++;
          buyLog(container, '[' + (i + 1) + '/' + plan.length + '] OK  ' + p.buff + '  (' + p.currency + ' ' + fmt(p.unit) + ')');
        } catch (e) { err++; buyLog(container, '[' + (i + 1) + '/' + plan.length + '] ERR ' + p.buff + ': ' + e); }
        await sleep(650);
      }
      buyLog(container, 'Done: ' + ok + ' ok, ' + err + ' errors. Reloading shop and balances...');
      try { UI.bal = await readBalances(); } catch (e) { }
      UI.appliedMsg = 'Bought ' + ok + ' buffs' + (err ? (' \u2014 ' + err + ' errors, see the log') : '') + '.';
      buildData();
      renderInto(container);
    })();
  }

  function renderInto(container) {
    ensureCss(container.ownerDocument);
    container.innerHTML = bodyHTML();
    // tab switch (ricorda la tab attiva → il re-render non salta a Gold)
    Array.prototype.forEach.call(container.querySelectorAll('.asb-tab'), function (t) {
      t.onclick = function () {
        UI.activeTab = t.dataset.tab;
        Array.prototype.forEach.call(container.querySelectorAll('.asb-tab'), function (x) { x.classList.remove('active'); });
        Array.prototype.forEach.call(container.querySelectorAll('.asb-panel'), function (x) { x.classList.remove('active'); });
        t.classList.add('active');
        container.querySelector('[data-panel="' + t.dataset.tab + '"]').classList.add('active');
      };
    });
    // boss toggle (perks del boss corrente o dell'altra settimana)
    Array.prototype.forEach.call(container.querySelectorAll('.asb-bossbtn'), function (b) {
      b.onclick = function () {
        if (b.getAttribute('data-boss') === UI.bossId) return;
        collectInputs(container);
        commit();
        UI.bossId = b.getAttribute('data-boss');
        buildData();
        renderInto(container);
      };
    });
    // frecce ordine Coin: sposta + salva subito (auto-persist)
    Array.prototype.forEach.call(container.querySelectorAll('.asb-ord'), function (btn) {
      btn.onclick = function () {
        if (btn.disabled) return;
        collectInputs(container);
        var i = +btn.dataset.i, dir = btn.dataset.dir, arr = UI.coinOrder;
        var j = (dir === 'up') ? i - 1 : i + 1;
        if (j >= 0 && j < arr.length) { var tmp = arr[i]; arr[i] = arr[j]; arr[j] = tmp; }
        UI.savedFlash = true;
        commit();                 // salva l'ordine immediatamente
        renderInto(container);    // ridisegna (resta sulla tab Coin)
      };
    });
    // blocco buff 🚫: desatura la riga ed esclude l'acquisto (auto-persist)
    Array.prototype.forEach.call(container.querySelectorAll('.asb-block'), function (btn) {
      btn.onclick = function () {
        collectInputs(container);
        var name = btn.getAttribute('data-block-name');
        var idx = UI.blocked.indexOf(name);
        if (idx >= 0) UI.blocked.splice(idx, 1); else UI.blocked.push(name);
        UI.savedFlash = true;
        commit();
        renderInto(container);
      };
    });
    // tab Acquista: PASSO 1 (prepara) → PASSO 2 (conferma esplicita)
    var buyStep1 = container.querySelector('#asb-buy-step1');
    var buyStep2 = container.querySelector('#asb-buy-step2');
    function buyShowStep(step) { if (buyStep1) buyStep1.hidden = (step !== 1); if (buyStep2) buyStep2.hidden = (step !== 2); }
    var calcBtn = container.querySelector('#asb-buy-calc');
    if (calcBtn) calcBtn.onclick = function () {
      calcBtn.disabled = true; UI.appliedMsg = null;
      Promise.resolve(readBalances()).then(function (bal) { UI.bal = bal; buildData(); renderInto(container); });
    };
    var runBtn = container.querySelector('#asb-buy-run');
    if (runBtn) runBtn.onclick = function () {
      var n = +runBtn.dataset.n;
      if (!n) return;
      UI.appliedMsg = null;
      buyShowStep(2);
      buyLog(container, 'Preview ready (' + n + ' buffs). Press the starred button to confirm.');
    };
    var buyCancel = container.querySelector('#asb-buy-cancel');
    if (buyCancel) buyCancel.onclick = function () { buyShowStep(1); buyLog(container, 'Buying cancelled.'); };
    var buyConfirm = container.querySelector('#asb-buy-confirm');
    if (buyConfirm) buyConfirm.onclick = function () { executePlan(container, buyConfirm); };
    // Import/Export tab
    var ioText = container.querySelector('#asb-io-text');
    var ioUrlInp = container.querySelector('#asb-io-url');
    if (ioText) ioText.addEventListener('input', function () { ioStar(container); });
    function ioEnsureText() { if (ioText && !ioText.value) ioText.value = JSON.stringify(buildEnvelope(), null, 2); return ioText ? ioText.value : ''; }
    var ioExp = container.querySelector('#asb-io-export');
    if (ioExp) ioExp.onclick = function () {
      ioText.value = JSON.stringify(buildEnvelope(), null, 2);
      ioStar(container);
      ioStatus(container, 'Exported ' + ioText.value.length + ' chars. Copy or download it.');
    };
    var ioCopy = container.querySelector('#asb-io-copy');
    if (ioCopy) ioCopy.onclick = function () {
      var txt = ioEnsureText(); ioStar(container);
      copyText(txt).then(function () { ioStatus(container, 'Copied to clipboard.'); }, function (e) { ioStatus(container, 'Copy failed: ' + e.message); });
    };
    var ioDl = container.querySelector('#asb-io-download');
    if (ioDl) ioDl.onclick = function () {
      var txt = ioEnsureText(); ioStar(container); var d = new Date(); function p(n) { return (n < 10 ? '0' : '') + n; }
      var name = 'asgard-autobuy-' + d.getFullYear() + p(d.getMonth() + 1) + p(d.getDate()) + '-' + p(d.getHours()) + p(d.getMinutes()) + '.json';
      downloadText(name, txt); ioStatus(container, 'Downloaded ' + name + '.');
    };
    // Import: PASSO 1 (anteprima) → PASSO 2 (conferma esplicita)
    var ioStep1 = container.querySelector('#asb-io-step1');
    var ioStep2 = container.querySelector('#asb-io-step2');
    function ioShowStep(step) { if (ioStep1) ioStep1.hidden = (step !== 1); if (ioStep2) ioStep2.hidden = (step !== 2); ioStar(container); }
    var ioImp = container.querySelector('#asb-io-import');
    if (ioImp) ioImp.onclick = function () {
      try {
        var r2 = normalizeConfig(JSON.parse(ioText.value));
        collectInputs(container);
        UI.ioPending = r2;                       // config in attesa di conferma
        var diffEl = container.querySelector('#asb-io-diff');
        if (diffEl) diffEl.textContent = diffSummary(UI.store, r2.store) + (r2.warnings.length ? '\nWarnings: ' + r2.warnings.join('; ') : '');
        ioShowStep(2);
        ioStatus(container, 'Preview ready. Press the starred "Confirm replace" button.', false);
      } catch (e) { ioStatus(container, 'Invalid JSON: ' + e.message, false); }
    };
    var ioCancel = container.querySelector('#asb-io-cancel');
    if (ioCancel) ioCancel.onclick = function () { UI.ioPending = null; ioShowStep(1); ioStatus(container, 'Import cancelled.', false); };
    var ioConfirm = container.querySelector('#asb-io-confirm');
    if (ioConfirm) ioConfirm.onclick = function () {
      var res = UI.ioPending;
      if (!res) { ioShowStep(1); return; }
      try {
        collectInputs(container);
        if (ioUrlInp) res.store.ioUrl = ioUrlInp.value || res.store.ioUrl;
        applyConfig(res.store);
        UI.ioUrl = res.store.ioUrl || UI.ioUrl;
        UI.ioPending = null;
        renderInto(container);                    // torna al passo 1, stessa finestra
        ioStatus(container, '\u2713 Imported and saved (bosses: ' + Object.keys(res.store.bosses).join(', ') + ').' + (res.warnings.length ? '\nWarnings: ' + res.warnings.join('; ') : ''), true);
        ioStar(container);
      } catch (e) { ioStatus(container, 'Import error: ' + e.message, false); }
    };
    var ioLoad = container.querySelector('#asb-io-load');
    if (ioLoad) ioLoad.onclick = function () {
      var url = ioUrlInp ? ioUrlInp.value : '';
      if (!url) { ioStatus(container, 'Enter a URL.'); return; }
      UI.ioUrl = url; if (UI.store) UI.store.ioUrl = url; saveStore(UI.store);
      ioStatus(container, 'Loading ' + url + ' ...');
      fetchText(url).then(function (txt) {
        if (ioText) ioText.value = txt;
        ioStar(container);
        ioStatus(container, 'Loaded ' + txt.length + ' chars. Press the starred "Import (preview)" button.', false);
      }, function (e) { ioStatus(container, 'Load failed: ' + e.message, false); });
    };
    ioStar(container);                            // stellina iniziale (su Load se la casella è vuota)
    setupCoinDnD(container);
  }

  // ---------------------------------------------------------------- DRAG & DROP (Coin order)
  // "Tieni premuto e trascina" su una riga Coin per spostare il buff nella posizione
  // di rilascio. Usa Pointer Events (funziona anche touch/penna). Riusa commit()+re-render.
  var DND = null;

  function clearDndMarks(rows) {
    rows.forEach(function (r) { r.classList.remove('asb-dragging', 'asb-drop-before', 'asb-drop-after'); });
  }

  function dndCleanup() {
    if (!DND) return;
    try {
      window.removeEventListener('pointermove', dndOnMove, true);
      window.removeEventListener('pointerup', dndOnUp, true);
      window.removeEventListener('pointercancel', dndOnUp, true);
    } catch (e) { }
    if (DND.ghost && DND.ghost.parentNode) DND.ghost.parentNode.removeChild(DND.ghost);
    clearDndMarks(DND.rows);
    DND.container.ownerDocument.body.classList.remove('asb-dragging');
    DND = null;
  }

  function dndOnMove(ev) {
    if (!DND) return;
    ev.preventDefault();
    DND.ghost.style.left = (ev.clientX + 14) + 'px';
    DND.ghost.style.top = (ev.clientY - 14) + 'px';
    // posizione di inserimento = numero di righe con punto-medio sopra il puntatore
    var over = DND.rows.length;
    for (var i = 0; i < DND.rows.length; i++) {
      var r = DND.rows[i].getBoundingClientRect();
      if (ev.clientY < r.top + r.height / 2) { over = i; break; }
    }
    DND.over = over;
    clearDndMarks(DND.rows);
    DND.rows[DND.from].classList.add('asb-dragging');
    if (over < DND.rows.length) DND.rows[over].classList.add('asb-drop-before');
    else if (DND.rows.length) DND.rows[DND.rows.length - 1].classList.add('asb-drop-after');
  }

  function dndOnUp() {
    if (!DND) return;
    var from = DND.from, over = (DND.over == null ? from : DND.over), container = DND.container;
    dndCleanup();
    var to = over > from ? over - 1 : over;   // l'indice si sposta dopo l'estrazione
    if (to !== from && to >= 0 && to < UI.coinOrder.length) {
      var arr = UI.coinOrder;
      var item = arr.splice(from, 1)[0];
      arr.splice(to, 0, item);
      collectInputs(container);
      UI.savedFlash = true;
      commit();
      renderInto(container);
    }
  }

  function beginDrag(container, tr, ev) {
    if (ev.button != null && ev.button !== 0) return;   // solo tasto sinistro
    ev.preventDefault();
    var rows = Array.prototype.slice.call(container.querySelectorAll('tr[data-row]'));
    var ghost = container.ownerDocument.createElement('div');
    ghost.id = 'asb-dnd-ghost';
    ghost.textContent = (tr.getAttribute('data-name') || '') + '  #' + (tr.dataset.row * 1 + 1);
    container.ownerDocument.body.appendChild(ghost);
    DND = { from: tr.dataset.row * 1, over: tr.dataset.row * 1, rows: rows, ghost: ghost, container: container };
    container.ownerDocument.body.classList.add('asb-dragging');
    try { ev.target.setPointerCapture && ev.target.setPointerCapture(ev.pointerId); } catch (e) { }
    window.addEventListener('pointermove', dndOnMove, true);
    window.addEventListener('pointerup', dndOnUp, true);
    window.addEventListener('pointercancel', dndOnUp, true);
    dndOnMove(ev);
  }

  function setupCoinDnD(container) {
    Array.prototype.forEach.call(container.querySelectorAll('tr[data-row] .asb-grip'), function (grip) {
      grip.addEventListener('pointerdown', function (ev) { beginDrag(container, grip.parentNode, ev); });
    });
  }

  function collectInputs(container) {
    var res = container.querySelector('#asb-reserve'); if (res) UI.cfg.gold.reserve = Math.round((parseFloat(res.value) || 0) * 1e6);
    Array.prototype.forEach.call(container.querySelectorAll('[data-gold-thr]'), function (inp) {
      var i = +inp.dataset.goldThr; UI.goldRows[i].minBalance = Math.round((parseFloat(inp.value) || 0) * 1e6);
    });
    Array.prototype.forEach.call(container.querySelectorAll('[data-gold-max]'), function (inp) {
      var i = +inp.dataset.goldMax; UI.goldRows[i].maxBuy = parseInt(inp.value, 10) || 0;
    });
  }

  function commit() {
    UI.cfg.gold.rules = UI.goldRows.map(function (r) { return { buff: r.buff, minBalance: r.minBalance, maxBuy: r.maxBuy }; });
    UI.cfg.coins.order = UI.coinOrder.slice();
    UI.cfg.blocked = UI.blocked.slice();
    if (UI.store) UI.store.ioUrl = UI.ioUrl || UI.store.ioUrl || '';
    return UI.store ? saveStore(UI.store) : false;
  }

  function openSettings() {
    var popup = W.HWHFuncs.popup;
    return Promise.resolve(readBalances()).then(function (bal) {
      UI.bal = bal;
      buildData();
      popup.customPopup(function (complete) {
        popup.setMsgText('Asgard Shop AutoBuy v' + VERSION);
        renderInto(popup.custom);
        popup.addButton({ msg: 'Save', color: 'green' }, function () { collectInputs(popup.custom); commit(); UI.savedFlash = true; renderInto(popup.custom); });
        popup.addButton({ msg: 'Reload', color: 'orange' }, function () { commit(); openSettings(); });
        popup.addButton({ result: false, isClose: true }, function () { popup.hide(); complete(false); });
        popup.show();
      });
    });
  }

  // ---------------------------------------------------------------- OTHERS BUTTON
  function addOthersButton() {
    var ops = W.HWHData.othersPopupButtons;
    if (!ops) return;
    if (ops.some(function (b) { return b && b._asb === true; })) return;
    ops.push({
      _asb: true,
      msg: 'Asgard Shop AutoBuy (settings)',
      title: 'Per-boss perks (current or other week), gold thresholds, buying (preview + confirm)',
      color: 'purple',
      result: function () { openSettings(); }
    });
  }

  // ---------------------------------------------------------------- INIT
  function init() {
    addOthersButton();
    var drift = null; try { drift = driftCheck(); } catch (e) { }
    if (drift && drift.issues.length) console.warn('[ASB] drift check FAILED: ' + drift.issues.join(' | '));
    else console.log('[ASB] drift check OK');
    W.ASB = {
      __loaded: true, version: VERSION,
      openSettings: openSettings,
      readShop: readShop, readBalances: readBalances,
      driftCheck: driftCheck,
      getConfig: loadConfig, saveConfig: saveConfig,
      icons: ASB_ICONS,
      computePlan: computePlan, buySlot: buySlot, executePlan: executePlan,
      buildEnvelope: buildEnvelope, normalizeConfig: normalizeConfig, applyConfig: applyConfig,
      diffSummary: diffSummary, fetchText: fetchText,
      getBoss: function () { return UI.bossId; },
      getLiveBoss: function () { return UI.liveBossId; },
      listBosses: function () { return Object.keys(ASB_CATALOG.bosses); },
      getStore: function () { return UI.store; },
      setBoss: function (id) { id = String(id); if (id === UI.bossId) return UI.bossId; UI.bossId = id; if (UI.store) UI.cfg = bossCfg(UI.store, id); buildData(); return UI.bossId; },
      getBlocked: function () { return UI.blocked.slice(); },
      toggleBlock: function (name) { var i = UI.blocked.indexOf(name); if (i >= 0) UI.blocked.splice(i, 1); else UI.blocked.push(name); commit(); return UI.blocked.slice(); },
      _: { buildData: buildData, UI: UI, reorder: function (i, dir) { var arr = UI.coinOrder; var j = dir === 'up' ? i - 1 : i + 1; if (j >= 0 && j < arr.length) { var t = arr[i]; arr[i] = arr[j]; arr[j] = t; } UI.savedFlash = true; commit(); return arr.slice(); } },
    };
    console.log('[ASB] v' + VERSION + ' ready (settings: per-boss perks, icons, drag&drop, Buy, import/export). window.ASB available.');
  }
})();
